CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
FIX="file://$(pwd)/web/usability/compare-score-plain-tooltips.html"
OUT="$(pwd)/web/usability/compare-score-plain-tooltips.png"

"$CHROME" --headless=new --disable-gpu --hide-scrollbars \
  --window-size=900,700 \
  --screenshot="$OUT" \
  "$FIX" 2>/dev/null

"$CHROME" --headless=new --disable-gpu --dump-dom --window-size=900,700 "$FIX" 2>/dev/null \
  | python3 -c 'import sys,re; html=sys.stdin.read(); m=re.search(rid="check"[^>]*>([^<]+)', html); print(m.group(1) if m else "NO CHECK")'

ls -lh "$OUT"

# Live index + viewer string checks
python3 << 'PY'
from pathlib import Path
idx = Path("web/index.html").read_text()
js = Path("web/viewer.js").read_text()
checks = {
  "index has Score th": "<th>Score</th>" in idx,
  "index no Metric th": "<th>Metric</th>" not in idx,
  "index no Douglas": "Douglas-Peucker" not in idx,
  "index no point-to-edge": "point-to-edge" not in idx,
  "index no streaming simplifier": "streaming simplifier" not in idx,
  "index has path shortener": "path shortener" in idx,
  "index DP match title": "DP allowed match error" in idx,
  "viewer Score th": "<th>Score</th>" in js,
  "viewer no Metric th": "<th>Metric</th>" not in js,
  "viewer no Douglas": "Douglas-Peucker" not in js,
  "viewer no point-to-edge": "point-to-edge" not in js,
  "viewer no streaming simplifier": "streaming simplifier" not in js,
  "viewer has path shortener": "path shortener" in js,
}
for k,v in checks.items():
  print(f"{'OK' if v else 'FAIL'}: {k}")
print("all_ok=", all(checks.values()))
PY

# Also verify Compare strip still one row at 900 via playwright if available
PW=$(find "$HOME/.npm/_npx" -type d -path '*/node_modules/playwright' 2>/dev/null | head -1)
if [ -n "$PW" ] && [ -d /tmp/node_modules/playwright ]; then PW_ROOT=/tmp; elif [ -n "$PW" ]; then PW_ROOT=$(dirname "$(dirname "$PW")"); else PW_ROOT=""; fi
echo "PW_ROOT=$PW_ROOT"
if [ -d /tmp/node_modules/playwright ]; then
  NODE_PATH=/tmp/node_modules node <<'NODE'
const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 900, height: 800 } });
  await page.addInitScript(() => { try { localStorage.setItem('simplify-viewer-tour-v1', '1'); } catch {} });
  await page.goto('file://' + path.resolve('web/index.html'));
  await page.evaluate(() => {
    const tour = document.getElementById('uiTour');
    if (tour) tour.hidden = true;
  });
  const r = await page.evaluate(() => {
    const head = document.getElementById('compareMetricsHead');
    const dp = document.querySelector('#baselineAlgoRow [data-algo="dp"]');
    const dots = document.querySelector('#baselineAlgoRow [data-algo="dots"]');
    const dpField = document.getElementById('baselineDpEpsField');
    return {
      scoreTh: head?.querySelector('th')?.textContent?.trim(),
      dpTitle: dp?.title || '',
      dotsTitle: dots?.title || '',
      dpFieldTitle: dpField?.title || '',
      scrollWidth: document.documentElement.scrollWidth,
      hasDouglas: (document.body.innerHTML.includes('Douglas-Peucker')),
      hasPointToEdge: (document.body.innerHTML.includes('point-to-edge')),
    };
  });
  console.log(JSON.stringify(r));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
NODE
fi

